import React, { useState } from 'react';

const MicRecorder = ({ onTranscript }) => {
  const [listening, setListening] = useState(false);

  const SpeechRecognition =
    window.SpeechRecognition || window.webkitSpeechRecognition;

  const handleListen = () => {
    if (!SpeechRecognition) {
      alert("Browser doesn't support Speech Recognition API");
      return;
    }

    const recognition = new SpeechRecognition();
    recognition.lang = 'en-US';
    recognition.interimResults = false;
    recognition.continuous = false;

    recognition.onstart = () => {
      console.log('🎙️ Mic started');
      setListening(true);
    };

    recognition.onend = () => {
      console.log('🛑 Mic stopped');
      setListening(false);
    };

    recognition.onerror = (event) => {
      console.error('❌ Mic error:', event.error);
      alert(`Speech recognition error: ${event.error}`);
      setListening(false);
    };

    recognition.onresult = (event) => {
      if (event.results.length > 0) {
        const text = event.results[0][0].transcript;
        console.log('📄 Transcript:', text);
        onTranscript(text); // Pass it to parent (App.js)
      } else {
        console.warn('⚠️ No speech detected');
      }
    };

    recognition.start();
  };

  return (
    <button onClick={handleListen} disabled={listening}>
      {listening ? '🎙️ Listening...' : '🎤 Start Speaking'}
    </button>
  );
};

export default MicRecorder;
